local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["1602f2591c8fac85"] = { "Questo è suolo sacro, infedele.", "." },
  ["160777a54698fc1c"] = { "<Il capitano Spaccateschi ruggisce in trionfo.>\n\nQuanto ancora possono resistere? Quanta altra feccia dell'⟦Alliance=Alleanza⟧ deve perire per mano dell'⟦Horde=Orda⟧ prima che si ritirino? Solo il tempo lo dirà, {race}...", "." },
  ["160a08531172207a"] = { "Sissignore! Grazie, signore!", "." },
  ["1612374162ba5393"] = { "Chi va là?", "." },
  ["16143a51383630d3"] = { "Perché lo chiedi a me, <novellino/novellina> imberbe?", "." },
  ["16149497e9942688"] = { "Dreadguard, tenete la linea. Fermate l'avanzata del Flagello!", "." },
  ["16162faaf825945b"] = { "Un altro studente. Magnifico. Ecco perché Lydon fa parte della Royal Society of Snobs e può fare ricerca, mentre a me tocca insegnare. Se vinco un altro premio per l'insegnamento, non me lo perdonerò mai!", "." },
  ["1627b0d351ee7472"] = { "L'⟦Argent Dawn=Alba d'Argento⟧ ti saluta, {class}! Mi chiamo Lightspark e faccio da quartiermastro autorizzato per l'equipaggiamento e il materiale dell'Alba.\n\nMan mano che combatti il male per nostro conto, guadagnandoti nel frattempo il nostro rispetto e la nostra fiducia, otterrai degli Emblemi del Valore dall'ufficiale Pureheart. Gli emblemi servono a due scopi: usali per migliorare la tua posizione nei nostri ranghi, oppure come moneta per acquistare oggetti speciali.\n\nMan mano che migliori la tua posizione presso l'Alba, scoprirai che avrai a disposizione sempre più oggetti.", "." },
  ["162aacd87f062c88"] = { "Non sapevo davvero cosa aspettarmi, Eris. Userò i miei poteri per aiutarti, se è questo che mi si chiede.", "." },
  ["16326c36348b0b26"] = { "Tu cerca Josef Gregorian. Lui in ⟦Magic Quarter=Quartiere della Magia⟧, su lato di anello interno di canale verde.", "." },
  ["1632e5a5f5292b82"] = { "Grazie! Grazie, <sacerdote/sacerdotessa>. Ora posso affrontare quegli gnoll con il tuo potere a sostenermi!", "." },
  ["163617b499c7a6fa"] = { "Vuoi rendere più potenti i tuoi demoni? Ti costerà, ma sei nel posto giusto.", "." },
  ["163974c470e3ca43"] = { "Mia nonna, che vive giù a ⟦Redridge=Crestarossa⟧, picchia i manichini più forte di te, <pivello/pivella>!", "." },
  ["163c1c242a315d72"] = { "Accidenti, non sapresti farti un panino senza qualcuno che ti dica come fare.", "." },
  ["1640eec6db77c860"] = { "Mi manca un pezzo del mio completo del Profeta e me ne serve uno nuovo.", "." },
  ["1642445c17ab815e"] = { "Vai alla Kodohide Leatherworkers nel Drag. Chiedi di Kamari.", "." },
  ["1645f8aeddbd88f4"] = { "Il comandante non è più lui da un po' di tempo. La sua amante è scomparsa durante uno scavo archeologico nel deserto a sud, svanita senza lasciare traccia! Davvero strano.\n\nImmagino che tu stia cercando lavoro? Devo forse prenderti a botte in testa per fartelo capire?", "." },
  ["16647770818fdb52"] = { "Applica la pittura di guerra dei Gordok!", "." },
  ["166539373df69a7a"] = { "Questa creatura soffre per gli effetti del vil... Dobbiamo porre fine alla sua agonia.", "." },
  ["166d2e3bace2bd1b"] = { "Affascinante. Continua, ti prego.", "." },
  ["167019b81b6ba643"] = { "Questa pozione sembra curare sempre meno danni ogni volta che la preparo, anche se uso gli stessi ingredienti. Se ne può trarre una sola conclusione: le piante stanno cambiando. Non so dire perché, né in cosa.", "." },
  ["167ec090f78254c3"] = { "%s lancia un possente ululato.", "." },
  ["16815028fb19ff30"] = { "Il Flagello nel ⟦Trade District=Quartiere del Commercio⟧! Addosso!", "." },
  ["1691ba16e688e8a7"] = { "Mmmmm, cibo. Non è troppo lontano, ma devi andare a nord, a Orgrimmar, e chiedere a uno dei grunt.", "." },
  ["1692647f2f858b63"] = { "So che sei lì, <ladro/ladra>. Lascia la mia casa o raggiungi gli altri ai piedi dell'albero del mondo.", "." },
  ["16963d0d82d49253"] = { "Non preoccupare, noi trova te.", "." },
  ["169840d6ed234116"] = { "La colpa è del dio che i troll Atal'ai avevano evocato. Distruggemmo la manifestazione fisica del dio e affondammo il tempio, ma il dio era molto più forte di quanto avessimo previsto. Il suo seme di corruzione aveva radici profonde e distorceva tutto ciò che incontrava.\n\nA Eranikus fu affidato il compito di vegliare sul tempio sommerso, perché né i semplici Atal'ai né il loro dio risorgessero mai più. Fu una vittima inconsapevole di questa corruzione, e noi lo fummo nel sottovalutarne la potenza.", "." },
  ["16a618744777c340"] = { "%s corre in aiuto di Stalagg!", "." },
  ["16a76899bd250321"] = { "Manufatto sacro appartiene a ⟦Blackrock=Roccianera⟧! Noi riprende!", "." },
  ["16aea2fb3ed7ef98"] = { "Impossibile! Sorgete, miei servitori! Servite ancora una volta il vostro padrone!", "." },
  ["16affbbe69660ae6"] = { "Cos'è successo alla tua compagnia di mercenari, The Veiled Blade?", "." },
  ["16b10c287cfbdf39"] = { "Dimostrami che sei amic<o/a> dei Gelkis, {name}.", "." },
  ["16bfe8eacdcd03cc"] = { "L'anziana Predastelle si trova a Scholomance, nelle ⟦Western Plaguelands=Terre Infette Occidentali⟧.", "." },
  ["16c097c773db762c"] = { "Bleah! È orribile!", "." },
  ["16c30e0dbe20c642"] = { "Guarda cosa hanno fatto al mio ragazzo.", "." },
  ["16c85df0b0c25d27"] = { "La forza del cuore è ciò che ti dà la determinazione per agire... un'azione radicata in intenti puri e sinceri. Mantenere l'equilibrio non significa essere compiacenti o banali.\n\nDevi mostrare determinazione per ciò in cui credi, e devi essere <disposto/disposta> a lottare per esso. L'orsa madre mostra una convinzione infinita nel proteggere i suoi piccoli, come l'orso anziano che protegge la sua tana. È questa determinazione, questa forza del cuore, che devi imparare a conoscere se vuoi padroneggiare la via dell'Artiglio.", "." },
  ["16d148cfe9a71537"] = { "Sacerdoti! Se continuate a curare così, tanto vale rendere le cose un po' più interessanti!", "." },
  ["16d2b5fda749020c"] = { "Appena fuori dalla porta principale della città c'è un cartello. Ti indicherà la torre degli zeppelin. Parla con il maestro degli zeppelin Frezza in cima alla torre.", "." },
  ["16d4697685c87f26"] = { "Noi vuole tanti famigli. Anya Maulray aiuta te a curarli. Tu trova lei a locanda, anello superiore di ⟦Trade Quarter=Quartiere del Commercio⟧.", "." },
  ["16d76d118578268e"] = { "A noi shen'dorei serve altra stoffa per rifornire le nostre scorte. Ogni tua donazione sarà messa a buon uso e accrescerà di certo la tua stima presso i Windshapers.", "." },
  ["16ddd301e9f687cd"] = { "Vestiti!? Non ti serviranno a niente contro del buon acciaio! Bah, se sei proprio <sicuro/sicura> di voler fare <il/la> <sarto/sarta>, vai da Magar's Cloth Goods nel Drag.", "." },
  ["16e301eb52e3caa4"] = { "Temo di non avere nulla da insegnare a chi ha la tua esperienza. Ma non sei ancora alla fine della strada. Parla con Lucan Cordell, là dietro il bancone. Ti guiderà nella prossima fase del tuo viaggio.", "." },
  ["16e7d84a2668ddb0"] = { "Ora è il tempo in cui l'anno è nuovo e la luna splende luminosa.\n\nÈ il nostro tempo... quello in cui gli antichi si risvegliano.", "." },
  ["16e80a3df89b9e7e"] = { "Noi entra in gilda? No? Ok, tu trova maestro di gilda su piattaforma est in ⟦Trade Quarter=Quartiere del Commercio⟧.", "." },
  ["16ede15083785b4f"] = { "Vincent! Tu e i tuoi miserabili simili non avrete più successo nel mettere in fuga me e i miei figli di quanto ne abbiano avuto quei pezzenti rimasugli del Kirin Tor.", "." },
  ["16f2581145db885a"] = { "%s scruta i moli da una parte all'altra.", "." },
  ["16f558bb7c01a384"] = { "Non è ancora giunta la tua ora. Ti aiuterò a tornare nel regno dei vivi... in cambio di un prezzo.", "." },
  ["16fc9b8d7497bb26"] = { "Il Catalogo d'autunno della ⟦Thorium Brotherhood=Fratellanza del Torio⟧:\n\nAll'interno troverai le offerte più calde per tutto ciò che ti serve all'avventura! Ti mostreremo perfino dove procurarti quei componenti e quelle forniture difficili da trovare.", "." },
})
